/* Install after 01_CreateTables.sql and 02_CreateIndexes.sql. */
IF OBJECT_ID('dbo.usp_HK_GetModuleData','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_GetModuleData;
GO
CREATE PROCEDURE dbo.usp_HK_GetModuleData @Module varchar(40), @EmployeeID int, @Filters xml=NULL
AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @FromDate date,@ToDate date,@BuildingID int,@FloorID int,@StaffID int,@VendorID int,@Status varchar(20),@FilterText varchar(30);
 SET @FilterText=NULLIF(@Filters.value('string((/Filters/FromDate)[1])','varchar(30)'),''); IF @FilterText IS NOT NULL SET @FromDate=CONVERT(date,@FilterText,23);
 SET @FilterText=NULLIF(@Filters.value('string((/Filters/ToDate)[1])','varchar(30)'),''); IF @FilterText IS NOT NULL SET @ToDate=CONVERT(date,@FilterText,23);
 SET @FilterText=NULLIF(@Filters.value('string((/Filters/BuildingID)[1])','varchar(30)'),''); IF @FilterText IS NOT NULL SET @BuildingID=CONVERT(int,@FilterText);
 SET @FilterText=NULLIF(@Filters.value('string((/Filters/FloorID)[1])','varchar(30)'),''); IF @FilterText IS NOT NULL SET @FloorID=CONVERT(int,@FilterText);
 SET @FilterText=NULLIF(@Filters.value('string((/Filters/StaffID)[1])','varchar(30)'),''); IF @FilterText IS NOT NULL SET @StaffID=CONVERT(int,@FilterText);
 SET @FilterText=NULLIF(@Filters.value('string((/Filters/VendorID)[1])','varchar(30)'),''); IF @FilterText IS NOT NULL SET @VendorID=CONVERT(int,@FilterText);
 SET @Status=NULLIF(@Filters.value('string((/Filters/Status)[1])','varchar(20)'),'');
 IF @Module='Buildings' SELECT BuildingID,BuildingCode,BuildingName,Address,Description,IsActive FROM dbo.HK_BuildingMaster ORDER BY BuildingName;
 ELSE IF @Module='Floors' SELECT f.FloorID,f.BuildingID,b.BuildingName,f.FloorNumber,f.FloorName,f.Description,f.IsActive FROM dbo.HK_FloorMaster f JOIN dbo.HK_BuildingMaster b ON b.BuildingID=f.BuildingID ORDER BY b.BuildingName,f.FloorNumber;
 ELSE IF @Module='Vendors' SELECT VendorID,VendorName,ContactPerson,ContactNumber,Email,ContractStartDate,ContractEndDate,ContractedManpower,SLARequirements,MonthlyContractCost,IsActive FROM dbo.HK_VendorMaster ORDER BY VendorName;
 ELSE IF @Module='Staff' SELECT s.StaffID,s.StaffCode,s.StaffName,s.EmployeeID,s.MobileNumber,s.StaffType,s.VendorID,v.VendorName,s.BuildingID,b.BuildingName,s.FloorID,f.FloorName,s.SupervisorID,s.ShiftName,s.JoiningDate,s.IsActive FROM dbo.HK_StaffMaster s LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=s.VendorID LEFT JOIN dbo.HK_BuildingMaster b ON b.BuildingID=s.BuildingID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=s.FloorID ORDER BY s.StaffName;
 ELSE IF @Module='Locations' SELECT l.LocationID,l.BuildingID,b.BuildingName,l.FloorID,f.FloorName,l.LocationCode,l.LocationName,l.LocationType,l.AssignedStaffID,s.StaffName AS AssignedStaffName,l.CleaningFrequency,l.IsActive FROM dbo.HK_LocationMaster l JOIN dbo.HK_BuildingMaster b ON b.BuildingID=l.BuildingID JOIN dbo.HK_FloorMaster f ON f.FloorID=l.FloorID LEFT JOIN dbo.HK_StaffMaster s ON s.StaffID=l.AssignedStaffID ORDER BY b.BuildingName,f.FloorNumber,l.LocationName;
 ELSE IF @Module='Activities' SELECT ActivityID,ActivityName,ActivityCategory,Description,Frequency,EstimatedMinutes,Priority,RequiresInspection,RequiresPhoto,IsActive FROM dbo.HK_ActivityMaster ORDER BY ActivityName;
 ELSE IF @Module='Schedules' SELECT s.ScheduleID,s.ScheduleDate,s.ActivityID,a.ActivityName,s.BuildingID,b.BuildingName,s.FloorID,f.FloorName,s.LocationID,l.LocationName,s.StaffID,st.StaffName,s.SupervisorID,s.StartTime,s.EndTime,s.Frequency,s.Priority FROM dbo.HK_ActivitySchedule s JOIN dbo.HK_ActivityMaster a ON a.ActivityID=s.ActivityID JOIN dbo.HK_BuildingMaster b ON b.BuildingID=s.BuildingID JOIN dbo.HK_FloorMaster f ON f.FloorID=s.FloorID JOIN dbo.HK_LocationMaster l ON l.LocationID=s.LocationID JOIN dbo.HK_StaffMaster st ON st.StaffID=s.StaffID WHERE s.IsActive=1 ORDER BY s.ScheduleDate DESC;
 ELSE IF @Module='Attendance' SELECT a.AttendanceID,a.AttendanceDate,a.StaffID,s.StaffName,s.VendorID,v.VendorName,a.BuildingID,b.BuildingName,a.FloorID,f.FloorName,a.ShiftName,a.LoginTime,a.LogoutTime,a.WorkingHours,a.AttendanceStatus,a.IsLate,a.IsEarlyDeparture,a.OvertimeHours,a.Remarks FROM dbo.HK_StaffAttendance a JOIN dbo.HK_StaffMaster s ON s.StaffID=a.StaffID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=a.VendorID LEFT JOIN dbo.HK_BuildingMaster b ON b.BuildingID=a.BuildingID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=a.FloorID WHERE (@FromDate IS NULL OR a.AttendanceDate>=@FromDate) AND (@ToDate IS NULL OR a.AttendanceDate<DATEADD(day,1,@ToDate)) AND (@BuildingID IS NULL OR a.BuildingID=@BuildingID) AND (@FloorID IS NULL OR a.FloorID=@FloorID) AND (@StaffID IS NULL OR a.StaffID=@StaffID) AND (@VendorID IS NULL OR a.VendorID=@VendorID) AND (@Status IS NULL OR a.AttendanceStatus=@Status) ORDER BY a.AttendanceDate DESC;
 ELSE IF @Module IN('DailyActivities','WeeklyMonthlyActivities','DashboardDetails','ConsolidatedReport')
 BEGIN
  IF @Module='DashboardDetails' SELECT (SELECT COUNT(*) FROM dbo.HK_StaffMaster WHERE IsActive=1 AND (@BuildingID IS NULL OR BuildingID=@BuildingID)) TotalStaff,(SELECT COUNT(*) FROM dbo.HK_StaffAttendance WHERE AttendanceDate=CONVERT(date,GETDATE()) AND AttendanceStatus='Present' AND (@BuildingID IS NULL OR BuildingID= @BuildingID)) PresentStaff,(SELECT COUNT(*) FROM dbo.HK_StaffAttendance WHERE AttendanceDate=CONVERT(date,GETDATE()) AND AttendanceStatus='Absent' AND (@BuildingID IS NULL OR BuildingID= @BuildingID)) AbsentStaff,COUNT(*) Scheduled,SUM(CASE WHEN aa.Status IN('Completed','Verified') THEN 1 ELSE 0 END) Completed,SUM(CASE WHEN aa.Status='Pending' THEN 1 ELSE 0 END) Pending,SUM(CASE WHEN aa.Status IN('Pending','In Progress') AND aa.ScheduledDate<CONVERT(date,GETDATE()) THEN 1 ELSE 0 END) Overdue,SUM(CASE WHEN aa.Status='Rejected' THEN 1 ELSE 0 END) Rejected,CAST(100.0*SUM(CASE WHEN aa.Status IN('Completed','Verified') THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0) AS decimal(5,2)) CompletionPercent,(SELECT COUNT(*) FROM dbo.HK_ActivityAssignment x JOIN dbo.HK_ActivityMaster m ON m.ActivityID=x.ActivityID WHERE m.RequiresInspection=1 AND x.Status='Completed') PendingInspections,(SELECT COUNT(*) FROM dbo.HK_Complaint WHERE Status NOT IN('Closed','Resolved') AND (@BuildingID IS NULL OR BuildingID=@BuildingID)) OpenComplaints,ISNULL((SELECT AVG(OverallScore) FROM dbo.HK_VendorEvaluation),0) VendorScore FROM dbo.HK_ActivityAssignment aa WHERE aa.ScheduledDate>=ISNULL(@FromDate,DATEADD(day,-30,CONVERT(date,GETDATE()))) AND aa.ScheduledDate<DATEADD(day,1,ISNULL(@ToDate,CONVERT(date,GETDATE()))) AND (@BuildingID IS NULL OR aa.BuildingID=@BuildingID) AND (@FloorID IS NULL OR aa.FloorID=@FloorID) AND (@StaffID IS NULL OR aa.StaffID=@StaffID) AND (@VendorID IS NULL OR aa.VendorID=@VendorID) AND (@Status IS NULL OR aa.Status=@Status);
  ELSE SELECT aa.AssignmentID,aa.ScheduledDate,b.BuildingName,f.FloorName,l.LocationName,a.ActivityName,s.StaffName,v.VendorName,aa.ScheduledStart,aa.ActualStart,aa.ActualEnd,aa.Status,aa.Remarks,a.Frequency,(SELECT TOP 1 ix.InspectionStatus FROM dbo.HK_Inspection ix WHERE ix.AssignmentID=aa.AssignmentID ORDER BY ix.InspectionDate DESC) InspectionStatus,CASE WHEN aa.ScheduledEnd IS NULL THEN 0 ELSE DATEDIFF(hour,CONVERT(datetime,aa.ScheduledDate)+CONVERT(datetime,aa.ScheduledEnd),ISNULL(aa.ActualEnd,GETDATE())) END DelayHours,aa.SupervisorID,aa.ActivityID,aa.LocationID,aa.StaffID FROM dbo.HK_ActivityAssignment aa JOIN dbo.HK_BuildingMaster b ON b.BuildingID=aa.BuildingID JOIN dbo.HK_FloorMaster f ON f.FloorID=aa.FloorID JOIN dbo.HK_LocationMaster l ON l.LocationID=aa.LocationID JOIN dbo.HK_ActivityMaster a ON a.ActivityID=aa.ActivityID JOIN dbo.HK_StaffMaster s ON s.StaffID=aa.StaffID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=aa.VendorID WHERE aa.IsActive=1 AND (@Module='DailyActivities' AND a.Frequency='Daily' OR @Module='WeeklyMonthlyActivities' AND a.Frequency IN('Weekly','Monthly') OR @Module='ConsolidatedReport') AND (@FromDate IS NULL OR aa.ScheduledDate>=@FromDate) AND (@ToDate IS NULL OR aa.ScheduledDate<DATEADD(day,1,@ToDate)) AND (@BuildingID IS NULL OR aa.BuildingID=@BuildingID) AND (@FloorID IS NULL OR aa.FloorID=@FloorID) AND (@StaffID IS NULL OR aa.StaffID=@StaffID) AND (@VendorID IS NULL OR aa.VendorID=@VendorID) AND (@Status IS NULL OR aa.Status=@Status) ORDER BY aa.ScheduledDate DESC;
 END
 ELSE IF @Module='Inspections' SELECT i.InspectionID,i.AssignmentID,i.InspectionDate,a.ActivityName,l.LocationName,s.StaffName,sp.StaffName SupervisorName,i.CleanlinessRating,i.QualityRating,i.InspectionStatus,i.ReworkRequired,i.Remarks FROM dbo.HK_Inspection i JOIN dbo.HK_ActivityAssignment x ON x.AssignmentID=i.AssignmentID JOIN dbo.HK_ActivityMaster a ON a.ActivityID=x.ActivityID JOIN dbo.HK_LocationMaster l ON l.LocationID=x.LocationID JOIN dbo.HK_StaffMaster s ON s.StaffID=i.StaffID JOIN dbo.HK_StaffMaster sp ON sp.StaffID=i.SupervisorID ORDER BY i.InspectionDate DESC;
 ELSE IF @Module='Complaints' SELECT c.ComplaintID,c.ComplaintNo,c.ComplaintDate,c.BuildingID,b.BuildingName,c.FloorID,f.FloorName,c.LocationID,l.LocationName,c.Category,c.Description,c.Priority,c.AssignedStaffID,s.StaffName AssignedStaffName,c.VendorID,v.VendorName,c.ExpectedResolution,c.Status,c.ResolutionRemarks FROM dbo.HK_Complaint c JOIN dbo.HK_BuildingMaster b ON b.BuildingID=c.BuildingID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=c.FloorID LEFT JOIN dbo.HK_LocationMaster l ON l.LocationID=c.LocationID LEFT JOIN dbo.HK_StaffMaster s ON s.StaffID=c.AssignedStaffID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=c.VendorID WHERE (@FromDate IS NULL OR c.ComplaintDate>=@FromDate) AND (@ToDate IS NULL OR c.ComplaintDate<DATEADD(day,1,@ToDate)) AND (@BuildingID IS NULL OR c.BuildingID=@BuildingID) AND (@FloorID IS NULL OR c.FloorID=@FloorID) AND (@StaffID IS NULL OR c.AssignedStaffID=@StaffID) AND (@VendorID IS NULL OR c.VendorID=@VendorID) AND (@Status IS NULL OR c.Status=@Status) ORDER BY c.ComplaintDate DESC;
 ELSE IF @Module='VendorPerformance' SELECT e.EvaluationID,e.VendorID,v.VendorName,e.EvaluationYear,e.EvaluationMonth,e.ManpowerScore,e.CompletionScore,e.QualityScore,e.SlaScore,e.ComplaintScore,e.OverallScore,e.Rating,e.Remarks FROM dbo.HK_VendorEvaluation e JOIN dbo.HK_VendorMaster v ON v.VendorID=e.VendorID ORDER BY e.EvaluationYear DESC,e.EvaluationMonth DESC;
 ELSE IF @Module='Inventory' SELECT t.TransactionID,t.TransactionDate,t.ConsumableID,m.ItemName,t.TransactionType,t.Quantity,m.UnitOfMeasure,t.VendorID,v.VendorName,t.StaffID,s.StaffName,t.BuildingID,b.BuildingName,t.FloorID,f.FloorName,(SELECT SUM(CASE WHEN z.TransactionType='In' THEN z.Quantity ELSE -z.Quantity END) FROM dbo.HK_ConsumableTransaction z WHERE z.ConsumableID=t.ConsumableID) StockBalance,t.Remarks FROM dbo.HK_ConsumableTransaction t JOIN dbo.HK_ConsumableMaster m ON m.ConsumableID=t.ConsumableID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=t.VendorID LEFT JOIN dbo.HK_StaffMaster s ON s.StaffID=t.StaffID LEFT JOIN dbo.HK_BuildingMaster b ON b.BuildingID=t.BuildingID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=t.FloorID ORDER BY t.TransactionDate DESC;
 ELSE IF @Module='Consumables' SELECT ConsumableID,ItemCode,ItemName,UnitOfMeasure,MinimumStock,IsActive FROM dbo.HK_ConsumableMaster ORDER BY ItemName;
 ELSE IF @Module='StaffPerformance' SELECT s.StaffID,s.StaffName,v.VendorName,COUNT(a.AssignmentID) AssignedTasks,SUM(CASE WHEN a.Status IN('Completed','Verified') THEN 1 ELSE 0 END) CompletedTasks,SUM(CASE WHEN a.Status='Verified' THEN 1 ELSE 0 END) OnTimeTasks,SUM(CASE WHEN a.Status IN('Pending','In Progress') THEN 1 ELSE 0 END) PendingTasks,SUM(CASE WHEN a.Status='Rejected' THEN 1 ELSE 0 END) RejectedTasks,SUM(CASE WHEN a.Status='Rework Required' THEN 1 ELSE 0 END) ReworkCount,ISNULL(AVG(CASE WHEN at.AttendanceStatus='Present' THEN 100.0 ELSE 0 END),0) AttendancePercent,ISNULL(AVG(CONVERT(decimal(5,2),i.QualityRating)),0) InspectionRating,ISNULL(AVG(CONVERT(decimal(5,2),i.QualityRating))*20,0) OverallScore FROM dbo.HK_StaffMaster s LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=s.VendorID LEFT JOIN dbo.HK_ActivityAssignment a ON a.StaffID=s.StaffID LEFT JOIN dbo.HK_StaffAttendance at ON at.StaffID=s.StaffID AND at.AttendanceDate>=DATEADD(day,-30,CONVERT(date,GETDATE())) LEFT JOIN dbo.HK_Inspection i ON i.StaffID=s.StaffID AND i.InspectionDate>=DATEADD(day,-30,GETDATE()) GROUP BY s.StaffID,s.StaffName,v.VendorName;
 ELSE RAISERROR('Unsupported Housekeeping module.',16,1);
END
GO
IF OBJECT_ID('dbo.usp_HK_GetLookups','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_GetLookups;
GO
CREATE PROCEDURE dbo.usp_HK_GetLookups @EmployeeID int AS
BEGIN SET NOCOUNT ON;
 SELECT BuildingID,BuildingName FROM dbo.HK_BuildingMaster WHERE IsActive=1 ORDER BY BuildingName;
 SELECT FloorID,FloorName FROM dbo.HK_FloorMaster WHERE IsActive=1 ORDER BY FloorNumber;
 SELECT StaffID,StaffName FROM dbo.HK_StaffMaster WHERE IsActive=1 ORDER BY StaffName;
 SELECT VendorID,VendorName FROM dbo.HK_VendorMaster WHERE IsActive=1 ORDER BY VendorName;
 SELECT ActivityID,ActivityName FROM dbo.HK_ActivityMaster WHERE IsActive=1 ORDER BY ActivityName;
 SELECT LocationID,LocationName FROM dbo.HK_LocationMaster WHERE IsActive=1 ORDER BY LocationName;
 SELECT AssignmentID,CONVERT(varchar(20),AssignmentID)+' - '+ActivityID FROM dbo.HK_ActivityAssignment WHERE IsActive=1;
 SELECT ConsumableID,ItemName FROM dbo.HK_ConsumableMaster WHERE IsActive=1 ORDER BY ItemName;
END
GO
/* Payload arrives as XML so this remains compatible with legacy SQL Server releases. */
IF OBJECT_ID('dbo.usp_HK_SaveModuleData','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_SaveModuleData;
GO
CREATE PROCEDURE dbo.usp_HK_SaveModuleData @Module varchar(40), @Payload xml, @EmployeeID int
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @ID int=0,@I1 int,@I2 int,@I3 int,@I4 int,@N1 nvarchar(2000),@N2 nvarchar(2000),@N3 nvarchar(2000),@N4 nvarchar(2000),@N5 nvarchar(2000),@N6 nvarchar(2000),@N7 nvarchar(2000),@N8 nvarchar(2000),@N9 nvarchar(2000),@Bit1 bit,@Bit2 bit,@Dec1 decimal(12,2);
 BEGIN TRY
 BEGIN TRANSACTION;
 SET @ID=ISNULL(@Payload.value('string((/Root/BuildingID)[1])','int'),0);
 IF @Module='Buildings'
 BEGIN
  SET @N1=@Payload.value('string((/Root/BuildingCode)[1])','varchar(30)'); SET @N2=@Payload.value('string((/Root/BuildingName)[1])','nvarchar(150)'); SET @N3=NULLIF(@Payload.value('string((/Root/Address)[1])','nvarchar(500)'),''); SET @N4=NULLIF(@Payload.value('string((/Root/Description)[1])','nvarchar(1000)'),''); SET @Bit1=ISNULL(@Payload.value('string((/Root/IsActive)[1])','bit'),1);
  IF @ID=0 INSERT dbo.HK_BuildingMaster(BuildingCode,BuildingName,Address,Description,IsActive,AddedBy) VALUES(@N1,@N2,@N3,@N4,@Bit1,@EmployeeID); ELSE UPDATE dbo.HK_BuildingMaster SET BuildingCode=@N1,BuildingName=@N2,Address=@N3,Description=@N4,IsActive=@Bit1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE BuildingID=@ID;
 END
 ELSE IF @Module='Floors'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/FloorID)[1])','int'),0); SET @I1=@Payload.value('string((/Root/BuildingID)[1])','int'); SET @I2=@Payload.value('string((/Root/FloorNumber)[1])','int'); SET @N1=@Payload.value('string((/Root/FloorName)[1])','nvarchar(100)'); SET @N2=NULLIF(@Payload.value('string((/Root/Description)[1])','nvarchar(500)'),'');
  IF @ID=0 INSERT dbo.HK_FloorMaster(BuildingID,FloorNumber,FloorName,Description,AddedBy) VALUES(@I1,@I2,@N1,@N2,@EmployeeID); ELSE UPDATE dbo.HK_FloorMaster SET BuildingID=@I1,FloorNumber=@I2,FloorName=@N1,Description=@N2,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE FloorID=@ID;
 END
 ELSE IF @Module='Vendors'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/VendorID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/VendorName)[1])','nvarchar(200)'); SET @N2=NULLIF(@Payload.value('string((/Root/ContactPerson)[1])','nvarchar(150)'),''); SET @N3=NULLIF(@Payload.value('string((/Root/ContactNumber)[1])','varchar(30)'),''); SET @N4=NULLIF(@Payload.value('string((/Root/Email)[1])','varchar(254)'),''); SET @N5=NULLIF(@Payload.value('string((/Root/SLARequirements)[1])','nvarchar(2000)'),''); SET @N6=@Payload.value('string((/Root/ContractedManpower)[1])','int'); SET @N9=NULLIF(@Payload.value('string((/Root/MonthlyContractCost)[1])','varchar(30)'),''); SET @Dec1=CASE WHEN @N9 IS NULL THEN NULL ELSE CONVERT(decimal(12,2),@N9) END; SET @N7=NULLIF(@Payload.value('string((/Root/ContractStartDate)[1])','varchar(10)'),''); SET @N8=NULLIF(@Payload.value('string((/Root/ContractEndDate)[1])','varchar(10)'),'');
  IF @ID=0 INSERT dbo.HK_VendorMaster(VendorName,ContactPerson,ContactNumber,Email,ContractStartDate,ContractEndDate,ContractedManpower,SLARequirements,MonthlyContractCost,AddedBy) VALUES(@N1,@N2,@N3,@N4,CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(date,@N7,23) END,CASE WHEN @N8 IS NULL THEN NULL ELSE CONVERT(date,@N8,23) END,@N6,@N5,@Dec1,@EmployeeID); ELSE UPDATE dbo.HK_VendorMaster SET VendorName=@N1,ContactPerson=@N2,ContactNumber=@N3,Email=@N4,ContractStartDate=CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(date,@N7,23) END,ContractEndDate=CASE WHEN @N8 IS NULL THEN NULL ELSE CONVERT(date,@N8,23) END,SLARequirements=@N5,ContractedManpower=@N6,MonthlyContractCost=@Dec1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE VendorID=@ID;
 END
 ELSE IF @Module='Staff'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/StaffID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/StaffCode)[1])','varchar(40)'); SET @N2=@Payload.value('string((/Root/StaffName)[1])','nvarchar(150)'); SET @N3=@Payload.value('string((/Root/StaffType)[1])','varchar(10)'); SET @N4=NULLIF(@Payload.value('string((/Root/MobileNumber)[1])','varchar(30)'),''); SET @N5=NULLIF(@Payload.value('string((/Root/VendorID)[1])','varchar(20)'),''); SET @N6=NULLIF(@Payload.value('string((/Root/BuildingID)[1])','varchar(20)'),''); SET @N7=NULLIF(@Payload.value('string((/Root/FloorID)[1])','varchar(20)'),'');
  SET @Bit1=ISNULL(@Payload.value('string((/Root/IsActive)[1])','bit'),1);
  SET @N8=NULLIF(@Payload.value('string((/Root/JoiningDate)[1])','varchar(10)'),'');
  IF @ID=0 INSERT dbo.HK_StaffMaster(StaffCode,StaffName,EmployeeID,MobileNumber,StaffType,VendorID,BuildingID,FloorID,ShiftName,JoiningDate,IsActive,AddedBy) VALUES(@N1,@N2,NULLIF(@Payload.value('string((/Root/EmployeeID)[1])','varchar(20)'),''),@N4,@N3,CASE WHEN @N5 IS NULL THEN NULL ELSE CONVERT(int,@N5) END,CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(int,@N6) END,CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(int,@N7) END,NULLIF(@Payload.value('string((/Root/ShiftName)[1])','nvarchar(50)'),''),CASE WHEN @N8 IS NULL THEN NULL ELSE CONVERT(date,@N8,23) END,@Bit1,@EmployeeID); ELSE UPDATE dbo.HK_StaffMaster SET StaffCode=@N1,StaffName=@N2,MobileNumber=@N4,StaffType=@N3,VendorID=CASE WHEN @N5 IS NULL THEN NULL ELSE CONVERT(int,@N5) END,BuildingID=CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(int,@N6) END,FloorID=CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(int,@N7) END,JoiningDate=CASE WHEN @N8 IS NULL THEN NULL ELSE CONVERT(date,@N8,23) END,IsActive=@Bit1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE StaffID=@ID;
 END
 ELSE IF @Module='Locations'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/LocationID)[1])','int'),0); SET @I1=@Payload.value('string((/Root/BuildingID)[1])','int'); SET @I2=@Payload.value('string((/Root/FloorID)[1])','int'); SET @N1=@Payload.value('string((/Root/LocationCode)[1])','varchar(50)'); SET @N2=@Payload.value('string((/Root/LocationName)[1])','nvarchar(150)'); SET @N3=@Payload.value('string((/Root/LocationType)[1])','nvarchar(50)'); SET @N4=@Payload.value('string((/Root/CleaningFrequency)[1])','varchar(20)'); SET @N5=NULLIF(@Payload.value('string((/Root/AssignedStaffID)[1])','varchar(20)'),'');
  IF @ID=0 INSERT dbo.HK_LocationMaster(BuildingID,FloorID,LocationCode,LocationName,LocationType,AssignedStaffID,CleaningFrequency,AddedBy) VALUES(@I1,@I2,@N1,@N2,@N3,CASE WHEN @N5 IS NULL THEN NULL ELSE CONVERT(int,@N5) END,@N4,@EmployeeID); ELSE UPDATE dbo.HK_LocationMaster SET BuildingID=@I1,FloorID=@I2,LocationCode=@N1,LocationName=@N2,LocationType=@N3,AssignedStaffID=CASE WHEN @N5 IS NULL THEN NULL ELSE CONVERT(int,@N5) END,CleaningFrequency=@N4,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE LocationID=@ID;
 END
 ELSE IF @Module='Consumables'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/ConsumableID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/ItemCode)[1])','varchar(40)'); SET @N2=@Payload.value('string((/Root/ItemName)[1])','nvarchar(150)'); SET @N3=@Payload.value('string((/Root/UnitOfMeasure)[1])','nvarchar(30)'); SET @Dec1=@Payload.value('string((/Root/MinimumStock)[1])','decimal(12,2)'); SET @Bit1=ISNULL(@Payload.value('string((/Root/IsActive)[1])','bit'),1);
  IF @ID=0 INSERT dbo.HK_ConsumableMaster(ItemCode,ItemName,UnitOfMeasure,MinimumStock,IsActive,AddedBy) VALUES(@N1,@N2,@N3,@Dec1,@Bit1,@EmployeeID); ELSE UPDATE dbo.HK_ConsumableMaster SET ItemCode=@N1,ItemName=@N2,UnitOfMeasure=@N3,MinimumStock=@Dec1,IsActive=@Bit1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ConsumableID=@ID;
 END
 ELSE IF @Module='Schedules'
 BEGIN
  SET @I1=@Payload.value('string((/Root/ActivityID)[1])','int'); SET @I2=@Payload.value('string((/Root/BuildingID)[1])','int'); SET @I3=@Payload.value('string((/Root/FloorID)[1])','int'); SET @I4=@Payload.value('string((/Root/LocationID)[1])','int'); SET @N1=@Payload.value('string((/Root/StaffID)[1])','int'); SET @N2=NULLIF(@Payload.value('string((/Root/SupervisorID)[1])','varchar(20)'),''); SET @N3=@Payload.value('string((/Root/ScheduleDate)[1])','date'); SET @N4=@Payload.value('string((/Root/Frequency)[1])','varchar(10)'); SET @N5=@Payload.value('string((/Root/Priority)[1])','varchar(10)'); SET @ID=ISNULL(@Payload.value('string((/Root/ScheduleID)[1])','int'),0);
  SET @N6=NULLIF(@Payload.value('string((/Root/StartTime)[1])','varchar(8)'),''); SET @N7=NULLIF(@Payload.value('string((/Root/EndTime)[1])','varchar(8)'),'');
  IF @ID=0 INSERT dbo.HK_ActivitySchedule(ActivityID,BuildingID,FloorID,LocationID,StaffID,SupervisorID,ScheduleDate,StartTime,EndTime,Frequency,Priority,AddedBy) VALUES(@I1,@I2,@I3,@I4,CONVERT(int,@N1),CASE WHEN @N2 IS NULL THEN NULL ELSE CONVERT(int,@N2) END,@N3,CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(time,@N6) END,CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(time,@N7) END,@N4,@N5,@EmployeeID); ELSE UPDATE dbo.HK_ActivitySchedule SET ActivityID=@I1,BuildingID=@I2,FloorID=@I3,LocationID=@I4,StaffID=CONVERT(int,@N1),SupervisorID=CASE WHEN @N2 IS NULL THEN NULL ELSE CONVERT(int,@N2) END,ScheduleDate=@N3,StartTime=CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(time,@N6) END,EndTime=CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(time,@N7) END,Frequency=@N4,Priority=@N5,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ScheduleID=@ID;
  IF @ID=0 SET @ID=SCOPE_IDENTITY(); IF NOT EXISTS(SELECT 1 FROM dbo.HK_ActivityAssignment WHERE ScheduleID=@ID) INSERT dbo.HK_ActivityAssignment(ScheduleID,ActivityID,BuildingID,FloorID,LocationID,StaffID,VendorID,SupervisorID,ScheduledDate,ScheduledStart,ScheduledEnd,Status,AddedBy) SELECT sch.ScheduleID,sch.ActivityID,sch.BuildingID,sch.FloorID,sch.LocationID,sch.StaffID,st.VendorID,sch.SupervisorID,sch.ScheduleDate,sch.StartTime,sch.EndTime,'Pending',@EmployeeID FROM dbo.HK_ActivitySchedule sch JOIN dbo.HK_StaffMaster st ON st.StaffID=sch.StaffID WHERE sch.ScheduleID=@ID;
 END
 ELSE IF @Module='Attendance'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/AttendanceID)[1])','int'),0); SET @I1=@Payload.value('string((/Root/StaffID)[1])','int'); SET @N1=@Payload.value('string((/Root/AttendanceDate)[1])','date'); SET @N2=@Payload.value('string((/Root/AttendanceStatus)[1])','varchar(15)'); SET @N3=NULLIF(@Payload.value('string((/Root/ShiftName)[1])','nvarchar(50)'),''); SET @Bit1=ISNULL(@Payload.value('string((/Root/IsLate)[1])','bit'),0); SET @Bit2=ISNULL(@Payload.value('string((/Root/IsEarlyDeparture)[1])','bit'),0);
  SET @N4=NULLIF(@Payload.value('string((/Root/OvertimeHours)[1])','varchar(20)'),'');
  IF @ID=0 INSERT dbo.HK_StaffAttendance(StaffID,AttendanceDate,ShiftName,AttendanceStatus,IsLate,IsEarlyDeparture,OvertimeHours,Remarks,AddedBy) VALUES(@I1,@N1,@N3,@N2,@Bit1,@Bit2,CASE WHEN @N4 IS NULL THEN 0 ELSE CONVERT(decimal(6,2),@N4) END,NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(1000)'),''),@EmployeeID); ELSE UPDATE dbo.HK_StaffAttendance SET AttendanceStatus=@N2,IsLate=@Bit1,IsEarlyDeparture=@Bit2,OvertimeHours=CASE WHEN @N4 IS NULL THEN 0 ELSE CONVERT(decimal(6,2),@N4) END,Remarks=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(1000)'),''),UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE AttendanceID=@ID;
 END
 ELSE IF @Module='Activities'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/ActivityID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/ActivityName)[1])','nvarchar(150)'); SET @N2=@Payload.value('string((/Root/ActivityCategory)[1])','nvarchar(80)'); SET @N3=NULLIF(@Payload.value('string((/Root/Description)[1])','nvarchar(1000)'),''); SET @N4=@Payload.value('string((/Root/Frequency)[1])','varchar(10)'); SET @N5=@Payload.value('string((/Root/Priority)[1])','varchar(10)'); SET @N6=NULLIF(@Payload.value('string((/Root/EstimatedMinutes)[1])','varchar(20)'),''); SET @I1=CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(int,@N6) END; SET @Bit1=ISNULL(@Payload.value('string((/Root/RequiresInspection)[1])','bit'),0); SET @Bit2=ISNULL(@Payload.value('string((/Root/RequiresPhoto)[1])','bit'),0);
  IF @ID=0 INSERT dbo.HK_ActivityMaster(ActivityName,ActivityCategory,Description,Frequency,EstimatedMinutes,Priority,RequiresInspection,RequiresPhoto,AddedBy) VALUES(@N1,@N2,@N3,@N4,@I1,@N5,@Bit1,@Bit2,@EmployeeID); ELSE UPDATE dbo.HK_ActivityMaster SET ActivityName=@N1,ActivityCategory=@N2,Description=@N3,Frequency=@N4,EstimatedMinutes=@I1,Priority=@N5,RequiresInspection=@Bit1,RequiresPhoto=@Bit2,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ActivityID=@ID;
 END
 ELSE IF @Module='Inspections'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/InspectionID)[1])','int'),0); SET @I1=@Payload.value('string((/Root/AssignmentID)[1])','int'); SET @I2=@Payload.value('string((/Root/CleanlinessRating)[1])','int'); SET @I3=@Payload.value('string((/Root/QualityRating)[1])','int'); SET @N1=@Payload.value('string((/Root/InspectionStatus)[1])','varchar(12)'); SET @Bit1=ISNULL(@Payload.value('string((/Root/ReworkRequired)[1])','bit'),0); SET @N2=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(2000)'),'');
  DECLARE @InspectedStaff int,@Supervisor int,@PriorStatus varchar(20); SELECT @InspectedStaff=StaffID,@PriorStatus=Status FROM dbo.HK_ActivityAssignment WHERE AssignmentID=@I1; SELECT TOP 1 @Supervisor=StaffID FROM dbo.HK_StaffMaster WHERE EmployeeID=@EmployeeID AND IsActive=1;
  IF @InspectedStaff IS NULL OR @Supervisor IS NULL RAISERROR('The task or supervisor staff mapping was not found.',16,1);
  IF @I2 NOT BETWEEN 1 AND 5 OR @I3 NOT BETWEEN 1 AND 5 OR @N1 NOT IN('Approved','Rejected') RAISERROR('Inspection ratings or status are invalid.',16,1);
  INSERT dbo.HK_Inspection(AssignmentID,StaffID,SupervisorID,CleanlinessRating,QualityRating,Remarks,InspectionStatus,ReworkRequired,AddedBy) VALUES(@I1,@InspectedStaff,@Supervisor,@I2,@I3,@N2,@N1,@Bit1,@EmployeeID); SET @ID=SCOPE_IDENTITY();
  UPDATE dbo.HK_ActivityAssignment SET Status=CASE WHEN @N1='Approved' THEN 'Verified' ELSE 'Rework Required' END,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE AssignmentID=@I1;
  INSERT dbo.HK_ActivityLog(AssignmentID,OldStatus,NewStatus,Remarks,ChangedBy) VALUES(@I1,@PriorStatus,CASE WHEN @N1='Approved' THEN 'Verified' ELSE 'Rework Required' END,@N2,@EmployeeID);
 END
 ELSE IF @Module='VendorPerformance'
 BEGIN
  DECLARE @Vendor int=@Payload.value('string((/Root/VendorID)[1])','int'),@Year smallint=@Payload.value('string((/Root/EvaluationYear)[1])','smallint'),@Month tinyint=@Payload.value('string((/Root/EvaluationMonth)[1])','tinyint'),@Manpower decimal(5,2),@Completion decimal(5,2),@Quality decimal(5,2),@Sla decimal(5,2),@Complaints decimal(5,2),@Overall decimal(5,2),@Rating varchar(12);
  SELECT @Manpower=CASE WHEN ContractedManpower=0 THEN 0 ELSE 100.0*COUNT(s.StaffID)/ContractedManpower END FROM dbo.HK_VendorMaster v LEFT JOIN dbo.HK_StaffMaster s ON s.VendorID=v.VendorID AND s.IsActive=1 WHERE v.VendorID=@Vendor GROUP BY ContractedManpower;
  SELECT @Completion=ISNULL(100.0*SUM(CASE WHEN Status IN('Completed','Verified') THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),0),@Sla=ISNULL(100.0*SUM(CASE WHEN Status='Verified' AND (ActualEnd IS NULL OR ActualEnd<=DATEADD(day,1,ScheduledDate)) THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),0) FROM dbo.HK_ActivityAssignment WHERE VendorID=@Vendor AND YEAR(ScheduledDate)=@Year AND MONTH(ScheduledDate)=@Month;
  SELECT @Quality=ISNULL(AVG(CONVERT(decimal(5,2),i.QualityRating))*20,0) FROM dbo.HK_Inspection i JOIN dbo.HK_ActivityAssignment a ON a.AssignmentID=i.AssignmentID WHERE a.VendorID=@Vendor AND YEAR(i.InspectionDate)=@Year AND MONTH(i.InspectionDate)=@Month;
  SELECT @Complaints=ISNULL(100.0*SUM(CASE WHEN Status IN('Resolved','Closed') THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),0) FROM dbo.HK_Complaint WHERE VendorID=@Vendor AND YEAR(ComplaintDate)=@Year AND MONTH(ComplaintDate)=@Month;
  SET @Manpower=ISNULL(@Manpower,0); SET @Completion=ISNULL(@Completion,0); SET @Quality=ISNULL(@Quality,0); SET @Sla=ISNULL(@Sla,0); SET @Complaints=ISNULL(@Complaints,0); SET @Overall=(@Manpower+@Completion+@Quality+@Sla+@Complaints)/5; SET @Rating=CASE WHEN @Overall>=90 THEN 'Excellent' WHEN @Overall>=75 THEN 'Good' WHEN @Overall>=60 THEN 'Satisfactory' ELSE 'Needs Improvement' END;
  SET @N1=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(2000)'),'');
  IF EXISTS(SELECT 1 FROM dbo.HK_VendorEvaluation WHERE VendorID=@Vendor AND EvaluationYear=@Year AND EvaluationMonth=@Month) UPDATE dbo.HK_VendorEvaluation SET ManpowerScore=@Manpower,CompletionScore=@Completion,QualityScore=@Quality,SlaScore=@Sla,ComplaintScore=@Complaints,OverallScore=@Overall,Rating=@Rating,Remarks=@N1 WHERE VendorID=@Vendor AND EvaluationYear=@Year AND EvaluationMonth=@Month;
  ELSE INSERT dbo.HK_VendorEvaluation(VendorID,EvaluationYear,EvaluationMonth,ManpowerScore,CompletionScore,QualityScore,SlaScore,ComplaintScore,OverallScore,Rating,Remarks,AddedBy) VALUES(@Vendor,@Year,@Month,@Manpower,@Completion,@Quality,@Sla,@Complaints,@Overall,@Rating,@N1,@EmployeeID);
  SELECT @ID=EvaluationID FROM dbo.HK_VendorEvaluation WHERE VendorID=@Vendor AND EvaluationYear=@Year AND EvaluationMonth=@Month;
 END
 ELSE IF @Module IN('DailyActivities','WeeklyMonthlyActivities')
 BEGIN
  DECLARE @Task int=@Payload.value('string((/Root/AssignmentID)[1])','int'), @Status varchar(20)=@Payload.value('string((/Root/Status)[1])','varchar(20)'), @Remarks nvarchar(2000)=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(2000)'),''); IF @Status NOT IN('Pending','In Progress','Completed','Verified','Rejected','Rework Required') RAISERROR('Invalid task status.',16,1);
  DECLARE @OldStatus varchar(20); SELECT @OldStatus=Status FROM dbo.HK_ActivityAssignment WHERE AssignmentID=@Task; UPDATE dbo.HK_ActivityAssignment SET Status=@Status,Remarks=@Remarks,ActualStart=CASE WHEN @Status='In Progress' AND ActualStart IS NULL THEN GETDATE() ELSE ActualStart END,ActualEnd=CASE WHEN @Status IN('Completed','Verified') THEN GETDATE() ELSE ActualEnd END,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE AssignmentID=@Task;
  IF @@ROWCOUNT=0 RAISERROR('Task was not found.',16,1); INSERT dbo.HK_ActivityLog(AssignmentID,OldStatus,NewStatus,Remarks,ChangedBy) VALUES(@Task,@OldStatus,@Status,@Remarks,@EmployeeID); SET @ID=@Task;
 END
 ELSE IF @Module='Complaints'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/ComplaintID)[1])','int'),0); SET @I1=@Payload.value('string((/Root/BuildingID)[1])','int'); SET @N1=NULLIF(@Payload.value('string((/Root/FloorID)[1])','varchar(20)'),''); SET @N2=NULLIF(@Payload.value('string((/Root/LocationID)[1])','varchar(20)'),''); SET @N3=@Payload.value('string((/Root/Category)[1])','nvarchar(80)'); SET @N4=@Payload.value('string((/Root/Description)[1])','nvarchar(2000)'); SET @N5=@Payload.value('string((/Root/Priority)[1])','varchar(10)'); SET @N6=NULLIF(@Payload.value('string((/Root/AssignedStaffID)[1])','varchar(20)'),''); SET @N7=NULLIF(@Payload.value('string((/Root/VendorID)[1])','varchar(20)'),'');
  SET @N8=NULLIF(@Payload.value('string((/Root/ExpectedResolution)[1])','varchar(30)'),'');
  IF @ID=0 BEGIN INSERT dbo.HK_Complaint(BuildingID,FloorID,LocationID,Category,Description,Priority,AssignedStaffID,VendorID,ExpectedResolution,Status,ResolutionRemarks,AddedBy) VALUES(@I1,CASE WHEN @N1 IS NULL THEN NULL ELSE CONVERT(int,@N1) END,CASE WHEN @N2 IS NULL THEN NULL ELSE CONVERT(int,@N2) END,@N3,@N4,@N5,CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(int,@N6) END,CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(int,@N7) END,CASE WHEN @N8 IS NULL THEN NULL ELSE CONVERT(datetime,@N8,126) END,ISNULL(NULLIF(@Payload.value('string((/Root/Status)[1])','varchar(15)'),''),'Open'),NULLIF(@Payload.value('string((/Root/ResolutionRemarks)[1])','nvarchar(2000)'),''),@EmployeeID); SET @ID=SCOPE_IDENTITY(); END
  ELSE UPDATE dbo.HK_Complaint SET Status=ISNULL(NULLIF(@Payload.value('string((/Root/Status)[1])','varchar(15)'),''),Status),AssignedStaffID=CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(int,@N6) END,ResolutionRemarks=NULLIF(@Payload.value('string((/Root/ResolutionRemarks)[1])','nvarchar(2000)'),''),UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ComplaintID=@ID;
 END
 ELSE IF @Module='Inventory'
 BEGIN
  SET @I1=@Payload.value('string((/Root/ConsumableID)[1])','int'); SET @N1=@Payload.value('string((/Root/TransactionType)[1])','varchar(6)'); SET @Dec1=@Payload.value('string((/Root/Quantity)[1])','decimal(12,2)'); SET @N5=NULLIF(@Payload.value('string((/Root/VendorID)[1])','varchar(20)'),''); SET @N6=NULLIF(@Payload.value('string((/Root/StaffID)[1])','varchar(20)'),''); SET @N7=NULLIF(@Payload.value('string((/Root/BuildingID)[1])','varchar(20)'),''); SET @N8=NULLIF(@Payload.value('string((/Root/FloorID)[1])','varchar(20)'),''); SET @N2=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(1000)'),'');
  INSERT dbo.HK_ConsumableTransaction(ConsumableID,TransactionType,Quantity,VendorID,StaffID,BuildingID,FloorID,Remarks,AddedBy) VALUES(@I1,@N1,@Dec1,CASE WHEN @N5 IS NULL THEN NULL ELSE CONVERT(int,@N5) END,CASE WHEN @N6 IS NULL THEN NULL ELSE CONVERT(int,@N6) END,CASE WHEN @N7 IS NULL THEN NULL ELSE CONVERT(int,@N7) END,CASE WHEN @N8 IS NULL THEN NULL ELSE CONVERT(int,@N8) END,@N2,@EmployeeID); SET @ID=SCOPE_IDENTITY();
 END
 ELSE RAISERROR('This module does not support saving yet.',16,1);
 INSERT dbo.HK_AuditLog(EntityName,EntityID,ActionName,PerformedBy) VALUES(@Module,@ID,'Save',@EmployeeID);
 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
  DECLARE @ErrorMessage nvarchar(2048)=ERROR_MESSAGE();
  RAISERROR(@ErrorMessage,16,1);
 END CATCH
END
GO
IF OBJECT_ID('dbo.usp_HK_DeactivateModuleData','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_DeactivateModuleData;
GO
CREATE PROCEDURE dbo.usp_HK_DeactivateModuleData @Module varchar(40), @RecordID int, @EmployeeID int AS
BEGIN SET NOCOUNT ON;
 DECLARE @Table sysname=CASE @Module WHEN 'Buildings' THEN 'HK_BuildingMaster' WHEN 'Floors' THEN 'HK_FloorMaster' WHEN 'Locations' THEN 'HK_LocationMaster' WHEN 'Staff' THEN 'HK_StaffMaster' WHEN 'Vendors' THEN 'HK_VendorMaster' WHEN 'Activities' THEN 'HK_ActivityMaster' WHEN 'Schedules' THEN 'HK_ActivitySchedule' WHEN 'Consumables' THEN 'HK_ConsumableMaster' END;
 IF @Table IS NULL RAISERROR('This record cannot be deactivated.',16,1);
 DECLARE @IDColumn sysname=CASE @Module WHEN 'Buildings' THEN 'BuildingID' WHEN 'Floors' THEN 'FloorID' WHEN 'Locations' THEN 'LocationID' WHEN 'Staff' THEN 'StaffID' WHEN 'Vendors' THEN 'VendorID' WHEN 'Activities' THEN 'ActivityID' WHEN 'Schedules' THEN 'ScheduleID' WHEN 'Consumables' THEN 'ConsumableID' END;
 DECLARE @SQL nvarchar(500)=N'UPDATE dbo.'+QUOTENAME(@Table)+N' SET IsActive=0,UpdatedBy=@U,UpdatedDate=GETDATE() WHERE '+QUOTENAME(@IDColumn)+N'=@I';
 EXEC sp_executesql @SQL,N'@U int,@I int',@U=@EmployeeID,@I=@RecordID;
 INSERT dbo.HK_AuditLog(EntityName,EntityID,ActionName,PerformedBy) VALUES(@Module,@RecordID,'Deactivate',@EmployeeID);
END
GO
